function centerMarkerOnMap(e, t) {
	e.flyTo(t.getLatLng(), 12)
}

function createAMarker(e, t, n) {
	let o = L.icon({
		iconUrl: "./assets/ip-address-images/icon-location.svg",
		iconSize: [32, 32],
		iconAnchor: [16, 32]
	}),
	a = L.marker([t.location.lat, t.location.lng], {
		icon: o
	}).addTo(e);

	centerMarkerOnMap(n, a)
	addMarkerEvents(a)
}

function addMarkerEvents(marker) {
	const { lat, lng } = marker.getLatLng()
	marker.bindPopup(`lat: ${lat}, long: ${lng}`)
}

function isAnIP(e) {
	const t = e.split(".")

	// IPv4 must have exactly 4 segments
	if (t.length !== 4) return false

	for (let o = 0; o < t.length; o++) {
		const n = parseInt(t[o], 10)

		if (isNaN(n) || n < 0 || n > 255 || n.toString() !== t[o]) {
			return false
		}
	}

	return true
}

function convertNullToSpace(e) {
	return e ? " " + e : ""
}

function correctDomainFormat(e) {
	e = e.toLowerCase()
   

	
	if (e.startsWith("https://")) {
		e = e.replace("https://", "")
	}

    if (e.startsWith("http://")) {
		e = e.replace("http://", "")
	}

	 if (e.startsWith("www.")) {
		e = e.replace("www.", "")
	}

	if (e.endsWith("/")) {
		e = e.slice(0, -1)
	}

	return e
}

function getInformation(e, t, n) {
	let o = "",
		a = ""

	ajaxFunction(
		a == e
			? {}
			: isAnIP(e)
			? { ipAddress: (o = e) }
			: { domain: correctDomainFormat(e) },
		t,
		n
	)
}

function ajaxFunction(e, t, n) {
	const paramValue = e.domain ? e.domain : e.ipAddress

	fetch(`/.netlify/functions/get_Information?data=${paramValue}`)
		.then(response => response.json())
		.then(data => {
			console.log(data)
			displayData(data, t, n)
		})
		.catch(error => {
			console.error("Error fetching data:", error)
			alert("Failed to retrieve IP information.")
		})
}

function displayData(e, t, n) {

	if (!e || !e.location) {
		console.error("Invalid API response:", e)
		alert("Failed to retrieve IP information.")
		return
	}

	document.getElementById("ip").innerText = e.ip

	document.getElementById("location").innerText =
		e.location.country +
		", " +
		e.location.region +
		convertNullToSpace(e.location.city) +
		convertNullToSpace(e.location.postalCode)

	document.getElementById("timezone").innerText =
		"UTC " + e.location.timezone

	document.getElementById("isp").innerText = e.isp

	createAMarker(t, e, n)
}
function getPermission(e, t, n) {
	if (n.trim() === "") {
		if (confirm("Permission to retrieve IP address")) {
			getInformation(n, e, t)
		}
	} else {
		getInformation(n, e, t)
	}
}

$(document).ready(function () {
	let e = L.map("map", {
		zoomControl: !1,
		minZoom: 3
	}).setView([52.8067, -2.1207], 9)

	L.tileLayer(
		"https://api.mapbox.com/styles/v1/{id}/tiles/{z}/{x}/{y}?access_token={accessToken}",
		{
			attribution:
				'Map data &copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors, Imagery \xa9 <a href="https://www.mapbox.com/">Mapbox</a>',
			maxZoom: 18,
			id: "mapbox/streets-v11",
			tileSize: 512,
			zoomOffset: -1,
			accessToken:
				"pk.eyJ1IjoiY25vcmYiLCJhIjoiY2t3M254MzRnMGN5ajJ4cHh3eWRyNjNsNyJ9.Juf1sSTeP4kgSornOTVC9Q"
		}
	).addTo(e)

	L.control.zoom({
		position: "bottomright"
	}).addTo(e)

	let t = L.layerGroup().addTo(e),
		n = document.getElementById("search")

	document.getElementById("submit").addEventListener("click", o => {
		o.preventDefault()
		t.clearLayers()
		getPermission(t, e, n.value)
	})
})